// Specification function: for reasoning - returns true if s starts with p.
// In Rust terms, s and p can be slices & [char].
fn starts_with(s: &[char], p: &[char]) -> bool {
    if p.is_empty() {
        return true;
    }
    if s.len() < p.len() {
        return false;
    }
    s.iter().zip(p.iter()).all(|(sc, pc)| sc == pc)
}

// Returns true if vector v has prefix p.
fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    starts_with(v.as_slice(), p.as_slice())
}

// Filters the input vector of sequences, retaining only those starting with p.
fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    xs.into_iter()
        .filter(|seq| has_prefix(seq, &p))
        .collect()
}